    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background: radial-gradient(circle at 20% 20%, var(--bg-b), transparent 45%),
                  radial-gradient(circle at 80% 80%, #ffe6d6, transparent 40%),
                  linear-gradient(145deg, var(--bg-a), #f1f7ff);
      font-family: "Trebuchet MS", "Verdana", sans-serif;
      overflow: hidden;
    }

    .stage {
      width: min(92vw, 640px);
      aspect-ratio: 4 / 3;
      position: relative;
      display: grid;
      place-items: center;
    }

    .shadow {
      position: absolute;
      width: 260px;
      height: 42px;
      border-radius: 999px;
      background: rgba(72, 55, 37, 0.18);
      filter: blur(4px);
      bottom: 50px;
      animation: breathe-shadow 2.8s ease-in-out infinite;
    }

    .cat {
      position: relative;
      width: 280px;
      height: 280px;
      animation: floaty 2.8s ease-in-out infinite;
      transform-origin: center bottom;
    }

    .tail {
      position: absolute;
      width: 92px;
      height: 120px;
      border: 12px solid var(--line);
      border-color: var(--line) var(--line) transparent transparent;
      border-radius: 75% 80% 0 0;
      right: 12px;
      top: 132px;
      transform-origin: 20% 85%;
      transform: rotate(18deg);
      animation: tail-wag 1.4s ease-in-out infinite;
      z-index: 0;
      background: linear-gradient(120deg, transparent 60%, rgba(255,255,255,0.24));
    }

    .body {
      position: absolute;
      width: 180px;
      height: 150px;
      background: var(--fur-main);
      border: 6px solid var(--line);
      border-radius: 52% 52% 42% 42%;
      bottom: 22px;
      left: 50%;
      transform: translateX(-50%);
      z-index: 1;
      overflow: hidden;
    }

    .body::before {
      content: "";
      position: absolute;
      width: 88px;
      height: 68px;
      border-radius: 50%;
      background: var(--white);
      left: 50%;
      bottom: 6px;
      transform: translateX(-50%);
    }

    .head {
      position: absolute;
      width: 190px;
      height: 166px;
      background: var(--fur-main);
      border: 6px solid var(--line);
      border-radius: 46% 46% 50% 50%;
      left: 50%;
      top: 46px;
      transform: translateX(-50%);
      z-index: 3;
      animation: breathe 2.8s ease-in-out infinite;
    }

    .ear {
      position: absolute;
      width: 62px;
      height: 72px;
      background: var(--fur-main);
      border: 6px solid var(--line);
      border-radius: 80% 20% 75% 20%;
      top: -38px;
      z-index: 2;
      transform-origin: bottom center;
      animation: ear-flick 3.2s ease-in-out infinite;
    }

    .ear::before {
      content: "";
      position: absolute;
      width: 30px;
      height: 38px;
      background: #ffc4cd;
      border-radius: 75% 20% 75% 25%;
      left: 12px;
      top: 14px;
      opacity: 0.9;
    }

    .ear.left {
      left: 18px;
      transform: rotate(-14deg);
    }

    .ear.right {
      right: 18px;
      transform: scaleX(-1) rotate(-14deg);
      animation-delay: 0.18s;
    }

    .face-patch {
      position: absolute;
      width: 136px;
      height: 96px;
      background: var(--white);
      border-radius: 50%;
      left: 50%;
      top: 58px;
      transform: translateX(-50%);
      opacity: 0.92;
    }

    .eye {
      position: absolute;
      width: 22px;
      height: 28px;
      background: var(--eye);
      border-radius: 48% 48% 52% 52%;
      top: 78px;
      animation: blink 4.2s infinite;
      transform-origin: center 62%;
    }

    .eye.left { left: 58px; }
    .eye.right { right: 58px; }

    .eye::after {
      content: "";
      position: absolute;
      width: 7px;
      height: 10px;
      border-radius: 50%;
      background: #ffffffd9;
      left: 4px;
      top: 4px;
    }

    .nose {
      position: absolute;
      width: 20px;
      height: 14px;
      background: var(--pink);
      border: 3px solid var(--line);
      border-radius: 45% 45% 60% 60%;
      left: 50%;
      top: 104px;
      transform: translateX(-50%);
      z-index: 5;
    }

    .mouth {
      position: absolute;
      width: 28px;
      height: 20px;
      left: 50%;
      top: 116px;
      transform: translateX(-50%);
    }

    .mouth::before,
    .mouth::after {
      content: "";
      position: absolute;
      width: 15px;
      height: 12px;
      border-bottom: 3px solid var(--line);
      border-radius: 0 0 12px 12px;
      top: 0;
    }

    .mouth::before { left: -1px; transform: rotate(8deg); }
    .mouth::after { right: -1px; transform: rotate(-8deg); }

    .whisker {
      position: absolute;
      width: 58px;
      height: 2px;
      background: var(--line);
      top: 116px;
      opacity: 0.9;
    }

    .whisker.left-1 { left: 0; transform: rotate(14deg); }
    .whisker.left-2 { left: 2px; top: 128px; transform: rotate(-4deg); }
    .whisker.right-1 { right: 0; transform: rotate(-14deg); }
    .whisker.right-2 { right: 2px; top: 128px; transform: rotate(4deg); }

    .stripe {
      position: absolute;
      width: 24px;
      height: 52px;
      border-radius: 40px;
      background: color-mix(in oklab, var(--fur-shadow) 85%, #000 5%);
      top: 36px;
      opacity: 0.8;
    }

    .stripe.s1 { left: 38px; transform: rotate(-16deg); }
    .stripe.s2 { right: 38px; transform: rotate(16deg); }
    .stripe.s3 {
      width: 20px;
      height: 40px;
      left: 50%;
      top: 34px;
      transform: translateX(-50%);
    }

    .paw {
      position: absolute;
      width: 48px;
      height: 44px;
      background: var(--fur-main);
      border: 5px solid var(--line);
      border-radius: 45% 45% 55% 55%;
      bottom: 12px;
      z-index: 4;
      animation: paw-hop 2.8s ease-in-out infinite;
    }

    .paw.left { left: 74px; }
    .paw.right { right: 74px; animation-delay: 0.08s; }

    .paw::before {
      content: "";
      position: absolute;
      width: 26px;
      height: 14px;
      background: #ffbdd0;
      border-radius: 50%;
      left: 50%;
      bottom: 4px;
      transform: translateX(-50%);
      opacity: 0.82;
    }

    .ground {
      position: absolute;
      width: 100%;
      height: 100%;
      pointer-events: none;
      overflow: hidden;
    }

    .sparkle {
      position: absolute;
      width: 8px;
      height: 8px;
      background: #fff7;
      border-radius: 50%;
      animation: twinkle 2.4s ease-in-out infinite;
    }

    .sparkle:nth-child(1) { left: 15%; top: 24%; animation-delay: 0.1s; }
    .sparkle:nth-child(2) { left: 78%; top: 18%; animation-delay: 0.7s; }
    .sparkle:nth-child(3) { left: 68%; top: 30%; animation-delay: 1.3s; }
    .sparkle:nth-child(4) { left: 26%; top: 12%; animation-delay: 1.9s; }

    @keyframes tail-wag {
      0%, 100% { transform: rotate(18deg); }
      50% { transform: rotate(-10deg); }
    }

    @keyframes blink {
      0%, 42%, 46%, 100% { transform: scaleY(1); }
      44% { transform: scaleY(0.1); }
    }

    @keyframes breathe {
      0%, 100% { transform: translateX(-50%) translateY(0) scale(1); }
      50% { transform: translateX(-50%) translateY(2px) scale(1.02); }
    }

    @keyframes breathe-shadow {
      0%, 100% { transform: scaleX(1); opacity: 0.2; }
      50% { transform: scaleX(0.93); opacity: 0.15; }
    }

    @keyframes floaty {
