using UnityEngine;

[RequireComponent(typeof(SpriteRenderer))]
public class CatIdle8Player : MonoBehaviour
{
    public float fps = 10f;
    private Sprite[] frames;
    private SpriteRenderer sr;
    private float timer;
    private int index;

    void Awake()
    {
        sr = GetComponent<SpriteRenderer>();
        frames = new Sprite[8];
        for (int i = 0; i < 8; i++)
        {
            string path = $"CatIdle8/idle8/{(i + 1).ToString("00")}";
            Texture2D tex = Resources.Load<Texture2D>(path);
            if (tex != null)
            {
                frames[i] = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0f), 96f);
            }
        }
        if (frames[0] != null) sr.sprite = frames[0];
    }

    void Update()
    {
        if (frames == null || frames.Length == 0) return;
        timer += Time.deltaTime;
        float frameTime = 1f / Mathf.Max(1f, fps);
        if (timer >= frameTime)
        {
            timer -= frameTime;
            index = (index + 1) % frames.Length;
            if (frames[index] != null) sr.sprite = frames[index];
        }
    }
}
CS
