import AppKit

final class PetWindow: NSWindow {
    init(contentRect: NSRect) {
        super.init(
            contentRect: contentRect,
            styleMask: [.borderless],
            backing: .buffered,
            defer: false
        )
        isOpaque = false
        backgroundColor = .clear
        hasShadow = true
        level = .floating
        collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        ignoresMouseEvents = false
        isMovableByWindowBackground = true
    }

    override var canBecomeKey: Bool { true }
}

final class PetView: NSView {
    private let imageView = NSImageView()
    private var frames: [NSImage] = []
    private var timer: Timer?
    private var index = 0
    private var fps: Double = 10

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        layer?.backgroundColor = NSColor.clear.cgColor

        imageView.frame = bounds
        imageView.autoresizingMask = [.width, .height]
        imageView.imageScaling = .scaleProportionallyUpOrDown
        addSubview(imageView)

        frames = loadFrames(folder: "Sprites/idle")
        imageView.image = frames.first
        startAnimation()

        let click = NSClickGestureRecognizer(target: self, action: #selector(toggleSpeed))
        addGestureRecognizer(click)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    private func loadFrames(folder: String) -> [NSImage] {
        guard let base = Bundle.module.resourceURL else { return [] }
        let dir = base.appendingPathComponent(folder)
        let fm = FileManager.default

        guard let urls = try? fm.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil)
            .filter({ $0.pathExtension.lowercased() == "png" })
            .sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) else {
            return []
        }

        return urls.compactMap { NSImage(contentsOf: $0) }
    }

    private func startAnimation() {
        timer?.invalidate()
        timer = Timer.scheduledTimer(withTimeInterval: 1.0 / fps, repeats: true) { [weak self] _ in
            guard let self, !self.frames.isEmpty else { return }
            self.index = (self.index + 1) % self.frames.count
            self.imageView.image = self.frames[self.index]
        }
        RunLoop.main.add(timer!, forMode: .common)
    }

    @objc private func toggleSpeed() {
        fps = (fps == 10) ? 16 : 10
        startAnimation()
    }

    deinit {
        timer?.invalidate()
    }
}

final class AppDelegate: NSObject, NSApplicationDelegate {
    private var window: NSWindow?

    func applicationDidFinishLaunching(_ notification: Notification) {
        let size = NSSize(width: 220, height: 220)
        let screen = NSScreen.main?.visibleFrame ?? NSRect(x: 0, y: 0, width: 1280, height: 800)
        let origin = NSPoint(x: screen.maxX - size.width - 40, y: screen.minY + 80)

        let window = PetWindow(contentRect: NSRect(origin: origin, size: size))
        window.contentView = PetView(frame: NSRect(origin: .zero, size: size))
        window.makeKeyAndOrderFront(nil)
        self.window = window

        let statusItem = NSStatusBar.system.statusItem(withLength: NSStatusItem.squareLength)
        statusItem.button?.title = "🐾"

        let menu = NSMenu()
        menu.addItem(NSMenuItem(title: "Quit", action: #selector(NSApplication.terminate(_:)), keyEquivalent: "q"))
        statusItem.menu = menu

        // Keep a strong reference via associated object-style capture
        objc_setAssociatedObject(self, "statusItem", statusItem, .OBJC_ASSOCIATION_RETAIN_NONATOMIC)
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
        false
    }
}

let app = NSApplication.shared
let delegate = AppDelegate()
app.delegate = delegate
app.setActivationPolicy(.accessory)
app.run()
SWIFT"}

