            let h = self.bounds.height * breath
            let x = (self.bounds.width - w) / 2.0
            let y = (self.bounds.height - h) / 2.0 + bob
            self.imageView.frame = NSRect(x: x, y: y, width: w, height: h)
            self.alphaValue = isDozing ? 0.92 : 1.0
        }
        RunLoop.main.add(motionTimer!, forMode: .common)
    }

