        fps = (fps == 10) ? 16 : 10
        startAnimation()
    }

    private func updateBehaviorState() {
        let now = Date()
        if now < nextBehaviorCheck { return }
        nextBehaviorCheck = now.addingTimeInterval(4.0)

        // Enter short doze occasionally.
        if dozeUntil == nil, Double.random(in: 0...1) < 0.22 {
            dozeUntil = now.addingTimeInterval(Double.random(in: 3.0...6.0))
            return
        }

        if let until = dozeUntil, now >= until {
            dozeUntil = nil
        }
    }

    private func mouseProximityBoost() -> CGFloat {
        guard let window = self.window else { return 0 }
        let mouse = NSEvent.mouseLocation
        let center = NSPoint(x: window.frame.midX, y: window.frame.midY)
