final class PetView: NSView {
    enum Mood: String {
        case idle = "Idle"
        case thinking = "Thinking"
        case success = "Success"
        case error = "Error"
    }

    private let imageView = NSImageView()
    private var frames: [NSImage] = []
    private var frameDurationsMs: [Double] = []
    private var moodFrames: [Mood: [NSImage]] = [:]
    private var moodDurations: [Mood: [Double]] = [:]
    private var frameTimer: Timer?
    private var motionTimer: Timer?
    private var index = 0
    private var speedMultiplier: Double = 1
    private var t: Double = 0
    private var dozeUntil: Date?
    private var nextBehaviorCheck = Date()
    private(set) var mood: Mood = .idle
    private var dragStartMouse: NSPoint?
    private var dragStartWindowOrigin: NSPoint?
    private var didDrag = false
    private var action: Action?

    private enum Action {
        case hop(start: Date)
        case celebrate(start: Date)
        case startle(start: Date)
    }

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        layer?.backgroundColor = NSColor.clear.cgColor

        imageView.frame = bounds
        imageView.autoresizingMask = [.width, .height]
        imageView.imageScaling = .scaleProportionallyUpOrDown
        imageView.wantsLayer = true
        imageView.layer?.magnificationFilter = .nearest
        imageView.layer?.minificationFilter = .nearest
        addSubview(imageView)

        moodFrames[.idle] = loadFrames(folder: "Sprites/codex_idle")
        moodFrames[.thinking] = loadFrames(folder: "Sprites/codex_thinking")
        moodFrames[.success] = loadFrames(folder: "Sprites/codex_success")
        moodFrames[.error] = loadFrames(folder: "Sprites/codex_error")
        moodDurations[.idle] = [280, 110, 110, 140, 140, 320]
        moodDurations[.thinking] = [150, 150, 150, 150, 150, 260]
        moodDurations[.success] = [140, 140, 140, 280]
        moodDurations[.error] = [140, 140, 140, 140, 140, 140, 140, 240]

        frames = moodFrames[.idle] ?? []
        frameDurationsMs = moodDurations[.idle] ?? []
        if frames.isEmpty { frames = loadFrames(folder: "Sprites/black_idle") }
        if frames.isEmpty { frames = loadFallbackBlackCat() }
        if frames.isEmpty { frames = loadFrames(folder: "Sprites/idle") }
        if frameDurationsMs.count != frames.count {
            frameDurationsMs = Array(repeating: 100, count: frames.count)
        }
        imageView.image = frames.first
        startAnimation()
        startMotion()

    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    private func loadFrames(folder: String) -> [NSImage] {
        guard let base = Bundle.module.resourceURL else { return [] }
        let dir = base.appendingPathComponent(folder)
        let fm = FileManager.default

        guard let urls = try? fm.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil)
            .filter({ $0.pathExtension.lowercased() == "png" })
            .sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) else {
            return []
        }

        return urls.compactMap { NSImage(contentsOf: $0) }
    }

    private func loadFallbackBlackCat() -> [NSImage] {
        guard
            let url = Bundle.module.url(forResource: "black-cat-minimal", withExtension: "svg", subdirectory: "Sprites"),
            let image = NSImage(contentsOf: url)
        else {
            return []
        }
        return Array(repeating: image, count: 8)
    }

    private func startAnimation() {
        frameTimer?.invalidate()
        scheduleNextFrame()
    }

    private func scheduleNextFrame() {
        frameTimer?.invalidate()
        let delayMs = frameDurationsMs.indices.contains(index) ? frameDurationsMs[index] : 100
        frameTimer = Timer.scheduledTimer(withTimeInterval: max(0.03, delayMs / 1000.0 / speedMultiplier), repeats: false) { [weak self] _ in
            guard let self, !self.frames.isEmpty else { return }
            if let until = self.dozeUntil, Date() < until {
                self.imageView.image = self.frames.first
                self.scheduleNextFrame()
                return
            }
            self.index = (self.index + 1) % self.frames.count
            self.imageView.image = self.frames[self.index]
            self.scheduleNextFrame()
        }
        RunLoop.main.add(frameTimer!, forMode: .common)
    }

    private func startMotion() {
        motionTimer?.invalidate()
        motionTimer = Timer.scheduledTimer(withTimeInterval: 1.0 / 60.0, repeats: true) { [weak self] _ in
            guard let self else { return }
            self.t += 1.0 / 60.0
            self.updateBehaviorState()

            let isDozing = (self.dozeUntil != nil && Date() < self.dozeUntil!)
            let motionSpeed = isDozing ? 1.2 : 2.4
            let breathSpeed = isDozing ? 1.0 : 2.0
            let bobAmount = isDozing ? 2.0…1727 chars truncated…ommon)
    }

    @objc private func toggleSpeed() {
        speedMultiplier = (speedMultiplier == 1) ? 1.55 : 1
        startAnimation()
    }

    override func mouseDown(with event: NSEvent) {
        guard let window = self.window else { return }
        dragStartMouse = NSEvent.mouseLocation
        dragStartWindowOrigin = window.frame.origin
        didDrag = false

        if event.clickCount >= 2 {
            action = .celebrate(start: Date())
            setMood(.success)
        }
    }

    override func mouseDragged(with event: NSEvent) {
        guard
            let window = self.window,
            let startMouse = dragStartMouse,
            let startOrigin = dragStartWindowOrigin
        else { return }

        let now = NSEvent.mouseLocation
        let dx = now.x - startMouse.x
        let dy = now.y - startMouse.y

        if abs(dx) > 2 || abs(dy) > 2 {
            didDrag = true
        }

        window.setFrameOrigin(NSPoint(x: startOrigin.x + dx, y: startOrigin.y + dy))
    }

    override func mouseUp(with event: NSEvent) {
        // Preserve click behavior only when no drag occurred.
        if !didDrag && event.clickCount < 2 {
            action = .hop(start: Date())
            toggleSpeed()
        }
        dragStartMouse = nil
        dragStartWindowOrigin = nil
    }

    func setMood(_ mood: Mood) {
        self.mood = mood
        switch mood {
        case .idle: speedMultiplier = 1
        case .thinking: speedMultiplier = 1
        case .success: speedMultiplier = 1.15
        case .error: speedMultiplier = 0.9
        }
        if let nextFrames = moodFrames[mood], !nextFrames.isEmpty {
            frames = nextFrames
            frameDurationsMs = moodDurations[mood] ?? Array(repeating: 100, count: nextFrames.count)
            index = 0
            imageView.image = frames.first
        }
        startAnimation()
    }

    private func updateBehaviorState() {
        let now = Date()
        if now < nextBehaviorCheck { return }
        nextBehaviorCheck = now.addingTimeInterval(4.0)

        if dozeUntil == nil, Double.random(in: 0...1) < 0.22 {
            dozeUntil = now.addingTimeInterval(Double.random(in: 3.0...6.0))
            return
        }

        if let until = dozeUntil, now >= until {
            dozeUntil = nil
        }
    }

    private func mouseProximityBoost() -> CGFloat {
        guard let window = self.window else { return 0 }
        let mouse = NSEvent.mouseLocation
        let center = NSPoint(x: window.frame.midX, y: window.frame.midY)
        let dx = mouse.x - center.x
        let dy = mouse.y - center.y
        let distance = sqrt(dx * dx + dy * dy)
        let threshold: CGFloat = 180
        if distance >= threshold { return 0 }
        return (threshold - distance) / threshold
    }

    private func actionEffect() -> (y: CGFloat, scale: CGFloat, squash: CGFloat) {
        guard let action else { return (0, 0, 0) }

        switch action {
        case .hop(let start):
            let elapsed = Date().timeIntervalSince(start)
            let duration: TimeInterval = 0.42
            if elapsed >= duration {
                self.action = nil
                return (0, 0, 0)
            }
            let p = CGFloat(elapsed / duration)
            return (sin(p * .pi) * 26, 0.03, p < 0.18 ? 0.08 : 0)

        case .celebrate(let start):
            let elapsed = Date().timeIntervalSince(start)
            let duration: TimeInterval = 1.2
            if elapsed >= duration {
                self.action = nil
                setMood(.idle)
                return (0, 0, 0)
            }
            let p = CGFloat(elapsed / duration)
            return (abs(sin(p * .pi * 4)) * 14, sin(p * .pi) * 0.12, 0)

        case .startle(let start):
            let elapsed = Date().timeIntervalSince(start)
            let duration: TimeInterval = 0.36
            if elapsed >= duration {
                self.action = nil
                return (0, 0, 0)
            }
            let p = CGFloat(elapsed / duration)
            return ((1 - p) * 10, (1 - p) * 0.12, 0)
        }
    }

    deinit {
        frameTimer?.invalidate()
        motionTimer?.invalidate()
    }
}

final class AppDelegate: NSObject, NSApplicationDelegate {
    private var window: NSWindow?
    private var statusItem: NSStatusItem?

    func applicationDidFinishLaunching(_ notification: Notification) {
        let size = NSSize(width: 144, height: 156)
        let screen = NSScreen.main?.visibleFrame ?? NSRect(x: 0, y: 0, width: 1280, height: 800)
        let origin = NSPoint(x: screen.midX - size.width / 2, y: screen.midY - size.height / 2)

        let window = PetWindow(contentRect: NSRect(origin: origin, size: size))
        window.contentView = PetView(frame: NSRect(origin: .zero, size: size))
        window.orderFrontRegardless()
        window.makeKeyAndOrderFront(nil)
        self.window = window
        print("MacPetApp window shown at \\(origin.x),\\(origin.y)")

