            contentRect: contentRect,
            styleMask: [.borderless],
            backing: .buffered,
            defer: false
        )
        isOpaque = false
        backgroundColor = .clear
        hasShadow = true
        level = .floating
        collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        ignoresMouseEvents = false
        isMovableByWindowBackground = true
    }

    override var canBecomeKey: Bool { true }

    override func mouseUp(with event: NSEvent) {
        super.mouseUp(with: event)
        snapToNearestEdge()
    }

    private func snapToNearestEdge() {
        guard let screen = screen ?? NSScreen.main else { return }
        let visible = screen.visibleFrame
        var frame = self.frame
        let margin: CGFloat = 12

        let leftDist = abs(frame.minX - visible.minX)
        let rightDist = abs(visible.maxX - frame.maxX)
        frame.origin.x = (leftDist < rightDist) ? (visible.minX + margin) : (visible.maxX - frame.width - margin)
        frame.origin.y = min(max(frame.origin.y, visible.minY + margin), visible.maxY - frame.height - margin)
        setFrame(frame, display: true, animate: true)
    }
}

